// UiChrome 实现：查找、缩放、截图、清数据/导入、保持焦点（打印/历史/下载/设置/设备工具栏/外部打开已随 AI 场景裁剪移除）
#include "ui_chrome.h" // 自身声明
#include <cmath> // log
#include <memory> // 智能指针
#include <vector> // 列表
#include "include/cef_browser.h" // CefBrowserHost
#include "include/cef_cookie.h" // CefCookieManager
#include "include/wrapper/cef_helpers.h" // CEF_REQUIRE_UI_THREAD
#include "server/cdp_client.h" // CdpClient
#include "server/pipe_client.h" // 管道响应/事件
#include "utils/js_builder.h" // js::Literal
#include "utils/json_util.h" // JSON 工具
#include "utils/logging.h" // 文件日志
#include "app_window.h" // AppWindow 接口
namespace {
const int kZoomMin = 50; // 缩放下限
const int kZoomMax = 200; // 缩放上限
const int kZoomStep = 10; // 缩放步长
double PercentToLevel(int percent) { return std::log(percent / 100.0) / std::log(1.2); } // 缩放换算 factor=1.2^level（用 1.01 会超出 CEF 上下限被钳位，导致一步跳到 500%/25%）
}
UiChrome::UiChrome(AppWindow* window) : window_(window) {} // 绑定窗口
void UiChrome::ApplyInitialSettings(int zoom_percent, bool keep_focus) { if (zoom_percent >= kZoomMin && zoom_percent <= kZoomMax) zoom_percent_ = zoom_percent; keep_focus_ = keep_focus; } // 应用 --settings 继承的缩放与保持焦点（缩放做区间钳位）
void UiChrome::ShowFind() { window_->SetFindVisible(true); } // 打开查找条
void UiChrome::HideFind() { find_started_ = false; window_->SetFindVisible(false); } // 关闭查找条并复位查找状态
void UiChrome::FindNext(bool forward) { CEF_REQUIRE_UI_THREAD(); const std::wstring text = window_->FindInputText(); CefRefPtr<CefBrowser> browser = window_->ActiveBrowser(); if (browser == nullptr || text.empty()) return; const bool next = find_started_; find_started_ = true; browser->GetHost()->Find(text, forward, false, next); } // Find(searchText, forward, matchCase, findNext)：首次 findNext=false 从头匹配，后续 true 前进/后退
void UiChrome::ZoomStep(int delta) { SetZoomPercent(zoom_percent_ + delta); } // 缩放步进
void UiChrome::SetZoomPercent(int percent) { if (percent < kZoomMin) percent = kZoomMin; if (percent > kZoomMax) percent = kZoomMax; zoom_percent_ = percent; ApplyZoom(); window_->SyncZoomUi(percent); } // 设置缩放：钳位后应用并同步 UI
void UiChrome::ApplyZoom() { CefRefPtr<CefBrowser> browser = window_->ActiveBrowser(); if (browser != nullptr) browser->GetHost()->SetZoomLevel(PercentToLevel(zoom_percent_)); } // 应用缩放到活动标签
void UiChrome::ToggleKeepFocus() { SetKeepFocus(!keep_focus_); } // 切换保持焦点
void UiChrome::SetKeepFocus(bool value) { keep_focus_ = value; if (keep_focus_) { CefRefPtr<CefBrowser> browser = window_->ActiveBrowser(); if (browser != nullptr) browser->GetHost()->SetFocus(true); } CefRefPtr<CefDictionaryValue> extra = MakeDict(); extra->SetBool("value", keep_focus_); ReportUi("keepFocus", extra); } // 设置保持焦点：开启时立即抢焦点并上报
void UiChrome::RunPipeCommand(int id, const std::string& cmd, CefRefPtr<CefDictionaryValue> args) { CEF_REQUIRE_UI_THREAD(); if (cmd == "ui_find") { std::string text; bool forward = true; ArgGetString(args, "text", text); ArgGetBool(args, "forward", forward); window_->SetFindVisible(true); window_->SetFindText(Utf8ToWide(text)); FindNext(forward); PipeClient::Respond(id, nullptr); return; } if (cmd == "ui_find_clear") { HideFind(); PipeClient::Respond(id, nullptr); return; } if (cmd == "ui_zoom") { int percent = 100; ArgGetInt(args, "percent", percent); SetZoomPercent(percent); CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetInt("percent", zoom_percent_); PipeClient::Respond(id, data); return; } if (cmd == "ui_screenshot") { ReportUi("screenshot", nullptr); PipeClient::Respond(id, nullptr); return; } if (cmd == "ui_clear_data") { ClearBrowsingData(id); return; } if (cmd == "ui_import_data") { ImportBrowsingData(id, args); return; } if (cmd == "ui_keep_focus") { bool value = !keep_focus_; ArgGetBool(args, "value", value); SetKeepFocus(value); CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetBool("value", keep_focus_); PipeClient::Respond(id, data); return; } if (cmd == "ui_fullscreen") { window_->ToggleFullscreen(); PipeClient::Respond(id, nullptr); return; } LOG_WARN("chrome", QStringLiteral("未知 ui 指令：%1").arg(QString::fromStdString(cmd))); PipeClient::RespondError(id, "未知指令: " + cmd); } // ui_* 指令分流：查找/缩放/截图/清数据/导入/保持焦点/全屏；未知指令报错
void UiChrome::ClearBrowsingData(int id) { CEF_REQUIRE_UI_THREAD(); LOG_INFO("chrome", QStringLiteral("清理浏览数据：id=%1").arg(id)); CefRefPtr<CdpClient> cdp = window_->ActiveCdp(); if (cdp != nullptr) { cdp->Call("Network.clearBrowserCookies", MakeDict(), [](bool ok, CefRefPtr<CefDictionaryValue>, const std::string&) {}); cdp->Call("Network.clearBrowserCache", MakeDict(), [](bool ok, CefRefPtr<CefDictionaryValue>, const std::string&) {}); } ClearStorageViaJs(); if (id != 0) { CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetBool("cookies", cdp != nullptr); data->SetBool("cache", cdp != nullptr); data->SetBool("storage", true); PipeClient::Respond(id, data); } ReportUi("clearData", nullptr); } // CEF 111 取消了 ClearCache/DeleteAllCookies 类接口，改走 CDP 浏览器级清理 + JS 清 storage
void UiChrome::ClearStorageViaJs() { CefRefPtr<CdpClient> cdp = window_->ActiveCdp(); if (cdp == nullptr) return; cdp->Evaluate("(function(){try{localStorage.clear();sessionStorage.clear();}catch(e){}return 'cleared';})()", false, [](bool ok, CefRefPtr<CefValue>, const std::string&) {}); } // 经 JS 清空 localStorage/sessionStorage（异常吞掉）
void UiChrome::ImportBrowsingData(int id, CefRefPtr<CefDictionaryValue> payload) { CEF_REQUIRE_UI_THREAD(); int applied = 0; CefRefPtr<CefCookieManager> manager = CefCookieManager::GetGlobalManager(nullptr); CefRefPtr<CefListValue> cookies = ArgGetList(payload, "cookies"); if (manager != nullptr && cookies != nullptr) { for (size_t i = 0; i < cookies->GetSize(); ++i) { CefRefPtr<CefDictionaryValue> item = cookies->GetDictionary(i); if (item == nullptr) continue; const std::string url = StrOf(item, "url"); if (url.empty()) continue; CefCookie cookie = {}; CefString(&cookie.name) = StrOf(item, "name"); CefString(&cookie.value) = StrOf(item, "value"); CefString(&cookie.domain) = StrOf(item, "domain"); const std::string path = StrOf(item, "path"); CefString(&cookie.path) = path.empty() ? std::string("/") : path; cookie.secure = BoolOf(item, "secure") ? 1 : 0; cookie.httponly = BoolOf(item, "httponly") ? 1 : 0; cookie.has_expires = false; if (manager->SetCookie(url, cookie, nullptr)) ++applied; } } CefRefPtr<CefDictionaryValue> storage = ArgGetDict(payload, "local_storage"); CefRefPtr<CdpClient> cdp = window_->ActiveCdp(); if (storage != nullptr && cdp != nullptr) { std::string script = "(function(){try{"; std::vector<CefString> keys; storage->GetKeys(keys); for (const CefString& key : keys) script += "localStorage.setItem(" + js::Literal(key.ToString()) + ",String(" + js::Literal(storage->GetString(key).ToString()) + "));"; script += "}catch(e){}return 'imported';})()"; cdp->Evaluate(script, false, [](bool ok, CefRefPtr<CefValue>, const std::string&) {}); } if (id != 0) { CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetInt("cookies", applied); PipeClient::Respond(id, data); } } // 导入：Cookie 经全局 CookieManager 写入（导入为会话 Cookie，cef_basetime_t 换算留给后续），local_storage 经 JS 写入，回传成功条数
void UiChrome::ReportUi(const std::string& item, CefRefPtr<CefDictionaryValue> extra) { CefRefPtr<CefDictionaryValue> data = extra != nullptr ? extra : MakeDict(); data->SetString("item", item); data->SetString("url", WideToUtf8(window_->ActiveUrl())); PipeClient::PostEvent("ui", data); } // 上报 ui 事件（附当前页地址）
